{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":28755,"isInternetEnabled":false,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"jupyter\":{\"outputs_hidden\":false},\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:09:34.944281Z\",\"iopub.execute_input\":\"2026-06-25T22:09:34.944554Z\",\"iopub.status.idle\":\"2026-06-25T22:10:47.328613Z\",\"shell.execute_reply.started\":\"2026-06-25T22:09:34.944525Z\",\"shell.execute_reply\":\"2026-06-25T22:10:47.327864Z\"}}\n!pip install monai --quiet\n!pip install git+https://github.com/NYUMedML/Neuro-JEPA.git --quiet\n!pip install scikit-learn matplotlib seaborn --quiet\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:14:11.903958Z\",\"iopub.execute_input\":\"2026-06-25T22:14:11.904744Z\",\"iopub.status.idle\":\"2026-06-25T22:14:11.910614Z\",\"shell.execute_reply.started\":\"2026-06-25T22:14:11.904696Z\",\"shell.execute_reply\":\"2026-06-25T22:14:11.909655Z\"}}\nimport os\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom torch.utils.data import Dataset, DataLoader, WeightedRandomSampler\nfrom pathlib import Path\nfrom sklearn.metrics import (\n    accuracy_score, f1_score, confusion_matrix, classification_report\n)\nimport matplotlib.pyplot as plt\nimport seaborn as sns\n\n# set your HuggingFace token so it can download the weights\nos.environ[\"HF_TOKEN\"] = \"XXXXXXXXXX\"\n\ndevice = \"cuda\" if torch.cuda.is_available() else \"cpu\"\nprint(f\"Device: {device}\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:14:13.122811Z\",\"iopub.execute_input\":\"2026-06-25T22:14:13.123088Z\",\"iopub.status.idle\":\"2026-06-25T22:14:13.132237Z\",\"shell.execute_reply.started\":\"2026-06-25T22:14:13.123064Z\",\"shell.execute_reply\":\"2026-06-25T22:14:13.131411Z\"}}\nimport json\n\nCACHE_PATH = \"/kaggle/input/datasets/em07adoz/shapes-cache/shapes_cache.json\"\nTSV_PATH   = \"/kaggle/input/datasets/em07adoz/partcipants-info\"\n\n# reload records from the cache your dataloader notebook built\nwith open(CACHE_PATH) as f:\n    cache = json.load(f)\n\nrecords = cache[\"records\"]\nprint(f\"Loaded {len(records)} subject records\")\n\n# confirm label distribution\nfrom collections import Counter\nLABEL_MAP = {\"Control\": 0, \"Dementia\": 1, \"Parkinson\": 2}\ninv_label = {v: k for k, v in LABEL_MAP.items()}\ncounts = Counter(inv_label[r[\"label\"]] for r in records)\nprint(f\"Class distribution: {dict(counts)}\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:14:18.327864Z\",\"iopub.execute_input\":\"2026-06-25T22:14:18.328571Z\",\"iopub.status.idle\":\"2026-06-25T22:14:18.335874Z\",\"shell.execute_reply.started\":\"2026-06-25T22:14:18.328539Z\",\"shell.execute_reply\":\"2026-06-25T22:14:18.335127Z\"}}\n%%writefile /kaggle/working/neurojepa_model.py\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom neurojepa.utils.init_utils import load_backbone_from_hf\n\n\nclass NeuroJEPABackbone(nn.Module):\n    \"\"\"\n    Neuro-JEPA encoder wrapper.\n\n    Architecture: 3D ViT-Base-MoE, patch=(16,16,16), embed_dim=768, 12 layers.\n    Trained with improved V-JEPA on 1.55M T1w/T2w/FLAIR scans.\n    HF model: NYUMedML/Neuro-JEPA, Paper: https://arxiv.org/abs/2606.14957\n\n    backbone = NeuroJEPABackbone.from_pretrained(\"NYUMedML/Neuro-JEPA\")\n    patchtokens, moe_scores = backbone(x)\n    # patchtokens shape: [B, N, D] — fixed spatial grid\n    \"\"\"\n\n    def __init__(self):\n        super().__init__()\n        self._backbone = None\n        self.hidden_dim = 768\n\n    def from_pretrained(self, model_id=\"NYUMedML/Neuro-JEPA\", device=None):\n        self._backbone = load_backbone_from_hf(model_id, device=device)\n        self.device = device or (\"cuda\" if torch.cuda.is_available() else \"cpu\")\n        return self\n\n    def load_dummy(self, img_size=(96, 108, 96), patch_size=16):\n        super(NeuroJEPABackbone, self).__init__()\n        self.hidden_dim = 768\n        patch_embed = nn.Conv3d(1, 768, kernel_size=patch_size, stride=patch_size)\n        encoder_layer = nn.TransformerEncoderLayer(\n            d_model=768, nhead=12, dim_feedforward=3072,\n            dropout=0.1, activation='gelu', batch_first=True\n        )\n        self._backbone = nn.ModuleDict({\n            'patch_embed': patch_embed,\n            'encoder': nn.TransformerEncoder(encoder_layer, num_layers=12),\n        })\n        self._backbone.eval()\n        self._img_size = img_size\n        self.device = \"cpu\"\n        return self\n\n    def forward(self, x):\n        if isinstance(self._backbone, nn.ModuleDict):\n            tokens = self._backbone['patch_embed'](x)\n            B, D, H, W, Dp = tokens.shape\n            tokens = tokens.flatten(2).transpose(1, 2)\n            tokens = self._backbone['encoder'](tokens)\n            n_experts = 4\n            moe_scores = torch.softmax(\n                torch.randn(B, tokens.size(1), n_experts, device=tokens.device),\n                dim=-1\n            )\n            return tokens, moe_scores\n        return self._backbone(x)\n\n    @property\n    def has_cls_token(self):\n        return False\n\n\nclass NeuroJEPAClassifier(nn.Module):\n    \"\"\"\n    Classification head for Neuro-JEPA.\n    Two pooling options: 'gap' or 'attn'.\n    \"\"\"\n\n    def __init__(self, hidden_dim=768, n_classes=3, pool='gap', dropout=0.3):\n        super().__init__()\n        self.pool = pool\n        if pool == 'attn':\n            self.attn = nn.Sequential(\n                nn.Linear(hidden_dim, 1),\n                nn.Softmax(dim=1),\n            )\n        self.classifier = nn.Sequential(\n            nn.Dropout(dropout),\n            nn.Linear(hidden_dim, n_classes),\n        )\n\n    def forward(self, patch_tokens):\n        if self.pool == 'gap':\n            pooled = patch_tokens.mean(dim=1)\n        elif self.pool == 'attn':\n            weights = self.attn(patch_tokens)\n            pooled = (patch_tokens * weights).sum(dim=1)\n        return self.classifier(pooled)\n\n    def get_attention_weights(self, patch_tokens):\n        if self.pool == 'attn':\n            return self.attn(patch_tokens)\n        return None\n\n    def features_before_pool(self, patch_tokens):\n        return patch_tokens\n\n\nclass NeuroJEPAGradCAM:\n    \"\"\"Grad-CAM for Neuro-JEPA with GAP-pooled classifier.\"\"\"\n\n    def __init__(self, backbone, classifier):\n        self.backbone = backbone\n        self.classifier = classifier\n        self.gradients = None\n\n    def _save_gradients(self, grad):\n        self.gradients = grad\n\n    def compute_saliency(self, x, target_class=None, resize_to=None):\n        self.backbone.eval()\n        self.classifier.eval()\n\n        x = x.detach().requires_grad_(True)\n        patch_tokens = self.backbone(x)[0]\n        patch_tokens.retain_grad()\n\n        logits = self.classifier(patch_tokens)\n        pred = logits.argmax(dim=-1).item() if target_class is None else target_class\n\n        self.classifier.zero_grad()\n        logits[0, pred].backward()\n        gradients = patch_tokens.grad\n\n        weights = gradients.mean(dim=(0, -1), keepdim=True)\n        cam = (patch_tokens * weights).sum(dim=-1)\n        cam = F.relu(cam)\n\n        N = cam.size(1)\n        grid_dims = self._infer_grid_dims(N, x.shape[2:])\n        if grid_dims is None:\n            return cam[0]\n\n        h, w, d = grid_dims\n        cam_3d = cam[0].reshape(h, w, d)\n        cam_3d = (cam_3d - cam_3d.min()) / (cam_3d.max() + 1e-8)\n\n        if resize_to is not None:\n            cam_3d = cam_3d.unsqueeze(0).unsqueeze(0)\n            cam_3d = F.interpolate(\n                cam_3d, size=resize_to, mode='trilinear', align_corners=False\n            )\n            cam_3d = cam_3d[0, 0]\n\n        return cam_3d\n\n    def _infer_grid_dims(self, N, vol_shape):\n        patch_size = 16\n        h = vol_shape[0] // patch_size\n        w = vol_shape[1] // patch_size\n        d = vol_shape[2] // patch_size\n        if h * w * d == N:\n            return (h, w, d)\n        return None\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:14:24.319393Z\",\"iopub.execute_input\":\"2026-06-25T22:14:24.320024Z\",\"iopub.status.idle\":\"2026-06-25T22:14:30.777771Z\",\"shell.execute_reply.started\":\"2026-06-25T22:14:24.319992Z\",\"shell.execute_reply\":\"2026-06-25T22:14:30.777155Z\"}}\n#NeuroJEPA Backbone\nimport sys\nsys.path.append(\"/kaggle/working\")\nfrom neurojepa_model import NeuroJEPABackbone, NeuroJEPAClassifier, NeuroJEPAGradCAM\n\n# load real weights - this downloads from HuggingFace\nbackbone = NeuroJEPABackbone().from_pretrained(\n    \"NYUMedML/Neuro-JEPA\",\n    device=device\n)\nbackbone.eval()\nprint(\"Neuro-JEPA backbone loaded.\")\nprint(f\"Hidden dim: {backbone.hidden_dim}\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:14:37.383109Z\",\"iopub.execute_input\":\"2026-06-25T22:14:37.383941Z\",\"iopub.status.idle\":\"2026-06-25T22:14:57.583476Z\",\"shell.execute_reply.started\":\"2026-06-25T22:14:37.383907Z\",\"shell.execute_reply\":\"2026-06-25T22:14:57.582715Z\"}}\n#MONAI Preprocessing Pipeline\nimport numpy as np\nfrom types import SimpleNamespace\nfrom neurojepa.data.transforms import loading_transforms, vit3d_transforms\n\ndef remove_nan(img):\n    img[np.isnan(img)] = 0.0\n    return img\n\ncfg = SimpleNamespace(data=SimpleNamespace(img_size=[96, 108, 96]))\n\n# static preprocessing - reorient, resample to 1mm, crop, resize, normalize\npreprocess = loading_transforms(\n    roi=cfg.data.img_size,\n    spacing=(1.0, 1.0, 1.0),\n    model_name=\"vit\",\n)\n\n# test mode = deterministic, no random augmentation\naugment = vit3d_transforms(cfg, mode=\"test\")\n\nprint(\"MONAI preprocessing pipeline ready.\")\nprint(\"Input will be resampled to 1mm isotropic, cropped to [96, 108, 96]\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:15:46.473768Z\",\"iopub.execute_input\":\"2026-06-25T22:15:46.475073Z\",\"iopub.status.idle\":\"2026-06-25T22:15:46.481957Z\",\"shell.execute_reply.started\":\"2026-06-25T22:15:46.475040Z\",\"shell.execute_reply\":\"2026-06-25T22:15:46.481148Z\"}}\n#dataset class\nclass NeuroJEPADataset(Dataset):\n    \"\"\"\n    Loads Nigerian MRI subjects and applies Neuro-JEPA's\n    exact MONAI preprocessing pipeline.\n    Output per subject: (1, 96, 108, 96) float tensor.\n    \"\"\"\n\n    def __init__(self, records):\n        self.records = records\n\n    def __len__(self):\n        return len(self.records)\n\n    def __getitem__(self, idx):\n        rec = self.records[idx]\n        try:\n            sample = preprocess({\"image\": rec[\"path\"]})\n            sample = augment(sample)\n            x = sample[\"image\"].float()   # (1, 96, 108, 96)\n        except Exception as e:\n            print(f\"  Error loading {rec['subject_id']}: {e}\")\n            x = torch.zeros(1, 96, 108, 96)\n\n        return {\n            \"image\":      x,\n            \"label\":      torch.tensor(rec[\"label\"]),\n            \"subject_id\": rec[\"subject_id\"],\n        }\n\nprint(\"Dataset class ready.\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:15:50.833420Z\",\"iopub.execute_input\":\"2026-06-25T22:15:50.834008Z\",\"iopub.status.idle\":\"2026-06-25T22:59:45.614931Z\",\"shell.execute_reply.started\":\"2026-06-25T22:15:50.833979Z\",\"shell.execute_reply\":\"2026-06-25T22:59:45.614027Z\"}}\nfrom tqdm.notebook import tqdm\n\nFEATURES_CACHE = \"/kaggle/working/neurojepa_features.pt\"\n\nif Path(FEATURES_CACHE).exists():\n    print(\"Loading cached features...\")\n    cache_data  = torch.load(FEATURES_CACHE)\n    all_features = cache_data[\"features\"]   # (N, 768)\n    all_labels   = cache_data[\"labels\"]     # (N,)\n    all_ids      = cache_data[\"subject_ids\"]\n    print(f\"Loaded features for {len(all_labels)} subjects.\")\n\nelse:\n    print(\"Extracting features from Neuro-JEPA backbone...\")\n    full_dataset = NeuroJEPADataset(records)\n    full_loader  = DataLoader(\n        full_dataset, batch_size=4, shuffle=False, num_workers=0\n    )\n\n    all_features = []\n    all_labels   = []\n    all_ids      = []\n\n    backbone.eval()\n    with torch.inference_mode():\n        for batch in tqdm(full_loader, desc=\"Extracting features\"):\n            x      = batch[\"image\"].to(device)    # (B, 1, 96, 108, 96)\n            labels = batch[\"label\"]\n            ids    = batch[\"subject_id\"]\n\n            patch_tokens, _ = backbone(x)          # (B, 576, 768)\n            pooled = patch_tokens.mean(dim=1)      # (B, 768) - global average pool\n\n            all_features.append(pooled.cpu())\n            all_labels.append(labels)\n            all_ids.extend(ids)\n\n    all_features = torch.cat(all_features, dim=0)  # (N, 768)\n    all_labels   = torch.cat(all_labels,   dim=0)  # (N,)\n\n    torch.save({\n        \"features\":    all_features,\n        \"labels\":      all_labels,\n        \"subject_ids\": all_ids,\n    }, FEATURES_CACHE)\n\n    print(f\"Features extracted and cached.\")\n    print(f\"Feature matrix shape: {all_features.shape}\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T22:59:45.988314Z\",\"iopub.execute_input\":\"2026-06-25T22:59:45.988571Z\",\"iopub.status.idle\":\"2026-06-25T22:59:45.993886Z\",\"shell.execute_reply.started\":\"2026-06-25T22:59:45.988547Z\",\"shell.execute_reply\":\"2026-06-25T22:59:45.992912Z\"}}\n#Featured Datasets\nclass FeatureDataset(Dataset):\n    \"\"\"Lightweight dataset over cached feature vectors.\"\"\"\n\n    def __init__(self, features, labels):\n        self.features = features\n        self.labels   = labels\n\n    def __len__(self):\n        return len(self.labels)\n\n    def __getitem__(self, idx):\n        return self.features[idx], self.labels[idx]\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T23:03:32.853685Z\",\"iopub.execute_input\":\"2026-06-25T23:03:32.854139Z\",\"iopub.status.idle\":\"2026-06-25T23:03:32.887024Z\",\"shell.execute_reply.started\":\"2026-06-25T23:03:32.854110Z\",\"shell.execute_reply\":\"2026-06-25T23:03:32.886268Z\"}}\n#stratified split\nimport torch\n\nRANDOM_SEED = 42\nTEST_FRAC   = 0.12\nN_FOLDS     = 5\n\ntorch.manual_seed(RANDOM_SEED)\nrng = torch.Generator().manual_seed(RANDOM_SEED)\n\nclasses   = torch.unique(all_labels)\ntrain_idx, test_idx = [], []\n\nfor c in classes:\n    idx    = torch.where(all_labels == c)[0]\n    idx    = idx[torch.randperm(len(idx), generator=rng)]\n    n_test = max(1, round(len(idx) * TEST_FRAC))\n    test_idx.extend(idx[:n_test].tolist())\n    train_idx.extend(idx[n_test:].tolist())\n\ntrain_feats  = all_features[train_idx]\ntrain_labels = all_labels[train_idx]\ntest_feats   = all_features[test_idx]\ntest_labels  = all_labels[test_idx]\n\nprint(f\"Train: {len(train_labels)}  |  Test: {len(test_labels)}\")\ninv_label = {v: k for k, v in LABEL_MAP.items()}\nfor name, labs in [(\"Train\", train_labels), (\"Test\", test_labels)]:\n    counts = Counter(inv_label[l.item()] for l in labs)\n    print(f\"  {name}: {dict(counts)}\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T23:03:37.933523Z\",\"iopub.execute_input\":\"2026-06-25T23:03:37.933815Z\",\"iopub.status.idle\":\"2026-06-25T23:03:40.786241Z\",\"shell.execute_reply.started\":\"2026-06-25T23:03:37.933768Z\",\"shell.execute_reply\":\"2026-06-25T23:03:40.785363Z\"}}\ndef make_weighted_sampler(labels):\n    counts  = torch.bincount(labels, minlength=3).float()\n    weights = 1.0 / counts\n    return WeightedRandomSampler(weights[labels], len(labels), replacement=True)\n\n\ndef train_fold(train_feats, train_labels, val_feats, val_labels,\n               n_epochs=50, lr=1e-3, dropout=0.3):\n\n    train_ds = FeatureDataset(train_feats, train_labels)\n    val_ds   = FeatureDataset(val_feats,   val_labels)\n\n    sampler      = make_weighted_sampler(train_labels)\n    train_loader = DataLoader(train_ds, batch_size=16, sampler=sampler)\n    val_loader   = DataLoader(val_ds,   batch_size=16, shuffle=False)\n\n    model     = NeuroJEPAClassifier(hidden_dim=768, n_classes=3,\n                                    pool='gap', dropout=dropout).to(device)\n    optimizer = torch.optim.Adam(model.parameters(), lr=lr, weight_decay=1e-4)\n    criterion = nn.CrossEntropyLoss()\n\n    best_val_acc = 0.0\n    best_weights = None\n\n    for epoch in range(n_epochs):\n        # train\n        model.train()\n        for feats, labels in train_loader:\n            feats, labels = feats.to(device), labels.to(device)\n            # classifier expects patch tokens [B, N, D]\n            # our cached features are [B, 768] - unsqueeze to [B, 1, 768]\n            feats = feats.unsqueeze(1)\n            optimizer.zero_grad()\n            logits = model(feats)\n            loss   = criterion(logits, labels)\n            loss.backward()\n            optimizer.step()\n\n        # validate\n        model.eval()\n        preds, trues = [], []\n        with torch.no_grad():\n            for feats, labels in val_loader:\n                feats  = feats.unsqueeze(1).to(device)\n                logits = model(feats)\n                preds.extend(logits.argmax(dim=1).cpu().tolist())\n                trues.extend(labels.tolist())\n\n        val_acc = accuracy_score(trues, preds)\n        if val_acc > best_val_acc:\n            best_val_acc = val_acc\n            best_weights = {k: v.clone() for k, v in model.state_dict().items()}\n\n    model.load_state_dict(best_weights)\n    return model, best_val_acc\n\n\n# run 5-fold CV\nperm      = torch.randperm(len(train_labels), generator=rng)\nfold_size = len(perm) // N_FOLDS\nfold_models  = []\nfold_val_acc = []\n\nfor fold in range(N_FOLDS):\n    val_start = fold * fold_size\n    val_end   = val_start + fold_size if fold < N_FOLDS - 1 else len(perm)\n\n    val_idx = perm[val_start:val_end]\n    tr_idx  = torch.cat([perm[:val_start], perm[val_end:]])\n\n    model, val_acc = train_fold(\n        train_feats[tr_idx],  train_labels[tr_idx],\n        train_feats[val_idx], train_labels[val_idx],\n    )\n    fold_models.append(model)\n    fold_val_acc.append(val_acc)\n    print(f\"Fold {fold+1}: val accuracy = {val_acc:.4f}\")\n\nprint(f\"\\nMean CV accuracy: {np.mean(fold_val_acc):.4f} ± {np.std(fold_val_acc):.4f}\")\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T23:03:44.833192Z\",\"iopub.execute_input\":\"2026-06-25T23:03:44.834006Z\",\"iopub.status.idle\":\"2026-06-25T23:03:44.856199Z\",\"shell.execute_reply.started\":\"2026-06-25T23:03:44.833974Z\",\"shell.execute_reply\":\"2026-06-25T23:03:44.855545Z\"}}\nbest_fold  = int(np.argmax(fold_val_acc))\nbest_model = fold_models[best_fold]\nbest_model.eval()\n\ntest_ds     = FeatureDataset(test_feats, test_labels)\ntest_loader = DataLoader(test_ds, batch_size=16, shuffle=False)\n\npreds, trues = [], []\nwith torch.no_grad():\n    for feats, labels in test_loader:\n        feats  = feats.unsqueeze(1).to(device)\n        logits = best_model(feats)\n        preds.extend(logits.argmax(dim=1).cpu().tolist())\n        trues.extend(labels.tolist())\n\nclass_names = [\"Control\", \"Dementia\", \"Parkinson\"]\n\nprint(\"=\" * 50)\nprint(f\"TEST SET RESULTS  (best fold: {best_fold+1})\")\nprint(\"=\" * 50)\nprint(f\"Accuracy : {accuracy_score(trues, preds):.4f}\")\nprint(f\"F1 (macro): {f1_score(trues, preds, average='macro'):.4f}\")\nprint(f\"F1 (weighted): {f1_score(trues, preds, average='weighted'):.4f}\")\nprint()\nprint(classification_report(trues, preds, target_names=class_names))\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-06-25T23:03:51.374132Z\",\"iopub.execute_input\":\"2026-06-25T23:03:51.374415Z\",\"iopub.status.idle\":\"2026-06-25T23:03:51.719462Z\",\"shell.execute_reply.started\":\"2026-06-25T23:03:51.374388Z\",\"shell.execute_reply\":\"2026-06-25T23:03:51.718868Z\"}}\ncm = confusion_matrix(trues, preds)\n\nplt.figure(figsize=(7, 6))\nsns.heatmap(cm, annot=True, fmt='d', cmap='Blues',\n            xticklabels=class_names, yticklabels=class_names)\nplt.title(\"Neuro-JEPA Linear Probe - Confusion Matrix\\nNigerian Brain MRI Dataset\")\nplt.ylabel(\"True Label\")\nplt.xlabel(\"Predicted Label\")\nplt.tight_layout()\nplt.savefig(\"/kaggle/working/confusion_matrix.png\", dpi=150)\nplt.show()\n\n# %% [code]\n","metadata":{"_uuid":"c78d42a5-7f29-41ac-9da4-b677bbfe5ae2","_cell_guid":"3138b076-6ed8-43d5-bcfe-89fc8914b1c4","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}